const ct={data:null,f:{type:'',name:'',phone:'',email:'',username:'',mac:'',plan:'',wallet:'',from:'',to:''},page:1,sort:'registered'};
const ago=t=>{if(!t)return 'Never';const s=Math.max(0,Math.round((Date.now()-t)/1000));if(s<60)return s+' seconds ago';const m=Math.round(s/60);if(m<60)return m+' minute'+(m===1?'':'s')+' ago';const h=Math.round(m/60);if(h<24)return h+' hour'+(h===1?'':'s')+' ago';const d=Math.round(h/24);if(d<45)return d+' day'+(d===1?'':'s')+' ago';const mo=Math.round(d/30);return mo<24?mo+' month'+(mo===1?'':'s')+' ago':Math.round(mo/12)+' years ago';};
function ctRows(){const d=ct.data,f=ct.f,has=(v,q)=>!q||String(v||'').toLowerCase().includes(q.toLowerCase());
 const from=f.from?Date.parse(f.from):null,to=f.to?Date.parse(f.to)+864e5:null;
 const rows=d.subscribers.filter(s=>(!f.type||s.service===f.type)&&has(s.name,f.name)&&has(s.phone,f.phone)&&has(s.email,f.email)&&has(s.username,f.username)&&has((s.boundMac||'')+' '+(s.lastMac||''),f.mac)&&has(s.planName,f.plan)&&has(s.balance,f.wallet)&&(from==null||(s.lastSeen&&s.lastSeen>=from))&&(to==null||(s.lastSeen&&s.lastSeen<to)));
 const key={registered:s=>-s.created,name:s=>s.name.toLowerCase(),seen:s=>-(s.lastSeen||0),expiry:s=>s.expiresAt||0}[ct.sort];return rows.sort((a,b)=>key(a)>key(b)?1:key(a)<key(b)?-1:0);}
